<div><label for="children">{{.t.children}}</label><div class="count"><button type="button" class="secondary" data-step="-1">−</button><input id="children" name="children" type="number" min="0" max="99" value="0"><button type="button" class="secondary" data-step="1">+</button></div></div></div>
{{else}}<div class="pair"><div><label for="start">{{.t.start_date}}</label><input id="start" name="start" type="date" min="{{.today}}" max="{{.last}}" required></div>
<div><label for="end">{{.t.end_date}}</label><input id="end" name="end" type="date" min="{{.today}}" required></div></div>
<label for="qty">{{.t.quantity}}</label><div class="count"><button type="button" class="secondary" data-step="-1">−</button><input id="qty" name="qty" type="number" min="1" max="{{.item.stock}}" value="1" required><button type="button" class="secondary" data-step="1">+</button></div>
{{end}}
