<div id="summary" hidden style="margin:16px 0"></div>
<button>{{.t.reserve}}</button></form></div>
<script>
(function(){
  var form=document.getElementById('reserve'),box=document.getElementById('summary'),timer=null,turn=0;
  function line(label,value,cls){var d=document.createElement('div');d.className='row '+(cls||'');var a=document.createElement('span'),b=document.createElement('span');a.textContent=label;b.textContent=value;d.appendChild(a);d.appendChild(b);return d}
  // The summary is for display only; the server works the price out again when the reservation is made.
  function update(){var mine=++turn;fetch('/api/availability?'+new URLSearchParams(new FormData(form)).toString()).then(function(r){return r.json()}).then(function(j){
    if(mine!==turn)return;box.textContent='';box.hidden=!j.complete;if(!j.complete)return;
    var p=document.createElement('p');p.className=j.available?'ok':'error';p.textContent=j.message;box.appendChild(p);
    (j.rows||[]).forEach(function(r){box.appendChild(line(r.label,r.value,r.cls))});}).catch(function(){box.hidden=true})}
  function soon(){clearTimeout(timer);timer=setTimeout(update,250)}
  form.addEventListener('input',soon);form.addEventListener('change',soon);
  form.querySelectorAll('button[data-step]').forEach(function(b){b.addEventListener('click',function(){var i=b.parentNode.querySelector('input');
    var v=(parseInt(i.value,10)||0)+parseInt(b.getAttribute('data-step'),10),lo=parseInt(i.min,10)||0,hi=parseInt(i.max,10)||999;i.value=Math.max(lo,Math.min(hi,v));soon()})});
  var s=document.getElementById('start'),e=document.getElementById('end');
  if(s&&e)s.addEventListener('change',function(){e.min=s.value;if(e.value&&e.value<s.value)e.value=s.value});
})();
</script>
{{template "bottom" .}}

