scripts.home:
// GET /  ?c=<category>  Items by category with "from" prices.
function handle(req) {
  const lang = langOf(req), t = texts(lang), cat = req.query.c || '';
  const lowest = {};
  for (const r of db.query('SELECT item_id, MIN(price) AS p FROM departures WHERE active = 1 AND price IS NOT NULL GROUP BY item_id')) lowest[r.item_id] = r.p;
  const categories = [], groups = [], seen = {};
  for (const i of db.query('SELECT * FROM items WHERE active = 1 ORDER BY id')) {
    const key = i.category || '';
    if (!seen[key]) {
      seen[key] = {key: key, name: loc(i, 'category', lang) || key, on: key === cat, items: []};
      if (key) categories.push(seen[key]);
      if (!cat || cat === key) groups.push(seen[key]);
    }
    let price = i.mode === 'departure' ? (i.price_adult || 0) : (i.price_day || 0);
    if (i.mode === 'departure' && lowest[i.id] !== undefined && lowest[i.id] < price) price = lowest[i.id];
    seen[key].items.push({id: i.id, name: loc(i, 'name', lang), image: i.image, price: money(price), unit: i.mode === 'departure' ? t.per_person : t.per_day,
      duration: loc(i, 'duration', lang) || ''});
  }
  return {template: 'home', data: page(req, {categories: categories, groups: groups, category: cat})};
}

scripts.item:
// GET /item/:id  A tour with its upcoming departures, or a rental with date pickers. ?error=<texts key>&n=<number> shows a message.
function handle(req) {
  const lang = langOf(req), t = texts(lang), b = business();
  const i = db.query('SELECT * FROM items WHERE id = ? AND active = 1', Number(req.params.id))[0];
  if (!i) return {template: 'not_found', data: page(req, {}), status: 404};
  const now = nowDubai(), ahead = b.days_ahead > 0 ? b.days_ahead : 60;
  const per = {booking: t.per_booking, person: i.mode === 'departure' ? t.per_person : t.per_unit, day: t.per_day};
  const item = {id: i.id, name: loc(i, 'name', lang), description: loc(i, 'description', lang), category: loc(i, 'category', lang), isDeparture: i.mode === 'departure',
    duration: loc(i, 'duration', lang) || '', included: loc(i, 'included', lang) || '', image: i.image || '', moreImages: [i.image2, i.image3].filter(Boolean),
    priceAdult: money(i.price_adult), priceChild: i.price_child === null ? '' : money(i.price_child), priceDay: money(i.price_day),
    priceWeek: i.price_week ? money(i.price_week) : '', minDays: i.min_days > 1 ? i.min_days : 0, stock: i.stock || 0,
    security: i.security_deposit > 0 ? money(i.security_deposit) : '', securityLabel: b.deposit_hold_enabled ? t.security_deposit_hold : t.security_deposit,
    documents: needsDocuments(i)};
  const error = /^error_\w+$/.test(req.query.error || '') ? errorText(t, req.query.error, whole(req.query.n, 0)) : '';
  return {template: 'item', data: page(req, {item: item, error: error, today: now.date, last: addDays(now.date, ahead),
    occurrences: i.mode === 'departure' ? occurrences(i, b, lang, 40) : [],
    extras: extrasFor(i).map(x => ({id: x.id, name: loc(x, 'name', lang), price: money(x.price), per: per[x.per] || ''}))})};
}

scripts.api_availability:
// GET /api/availability?item=&when=|start=&end=&qty=&adults=&children=&x<id>=1&lang=
// JSON for the live price summary on the item page: {complete, available, left, total, message, rows: [{label, value, cls}]}.
// For display only: POST /book prices and checks the reservation again.
function handle(req) {
  const lang = langOf(req), t = texts(lang), b = business();
  const i = db.query('SELECT * FROM items WHERE id = ? AND active = 1', Number(req.query.item))[0];
  if (!i) return {json: {complete: false, available: false, left: 0, message: t.not_found, rows: []}};
  const q = quote(i, req.query, b, 0);
  if (!q.ok) return {json: {complete: q.complete, available: false, left: q.n, message: errorText(t, q.error, q.n), rows: []}};
  return {json: {complete: true, available: true, left: q.left, days: q.days, total: q.total, vat: q.vat, pay_now: q.online,
    message: q.left + ' ' + (i.mode === 'departure' ? t.seats_left : t.available), rows: quoteRows(q, t, lang, true)}};
}

scripts.checkout:
// GET /checkout?item=&when=|start=&end=&qty=&adults=&children=&x<id>=1
// Shows the price worked out by the server and asks for the customer's details. Signed-out visitors are asked to sign in and come back here.
function handle(req) {
  const lang = langOf(req), t = texts(lang), b = business(), ql = lang === 'ar' ? '&lang=ar' : '';
  const i = db.query('SELECT * FROM items WHERE id = ? AND active = 1', Number(req.query.item))[0];
  if (!i) return {redirect: '/' + (lang === 'ar' ? '?lang=ar' : '')};
  const q = quote(i, req.query, b, 0);
  if (!q.ok) return {redirect: '/item/' + i.id + '?error=' + q.error + '&n=' + q.n + ql};
  const fields = [{name: 'item', value: String(i.id)}, {name: 'lang', value: lang}];
  for (const k of ['when', 'adults', 'children', 'start', 'end', 'qty']) if (req.query[k]) fields.push({name: k, value: req.query[k]});
  for (const id of q.extras) fields.push({name: 'x' + id, value: '1'});
  const r = {mode: q.mode, start_date: q.start, end_date: q.end, time: q.time, days: q.days, adults: q.adults, children: q.children, quantity: q.qty};
  return {template: 'checkout', data: page(req, {itemId: i.id, itemName: loc(i, 'name', lang), isDeparture: i.mode === 'departure',
    when: whenText(r, lang, t), guests: guestsText(r, t), rows: quoteRows(q, t, lang, false), fields: fields,
    card: q.online > 0, later: !!b.pay_later_enabled, payNow: money(q.online), balance: money(q.total - q.online), full: q.online >= q.total, total: money(q.total),
    customerName: req.user ? req.user.name : '', customerPhone: req.user ? req.user.phone : '',
    documents: q.documents, uploads: q.documents && !!req.user, depositHold: q.depositHold, security: money(q.security)})};
}

scripts.book:
// POST /book  form: item, when | start, end, qty, adults, children, x<extra id>, name, phone, notes, payment (card|later), lang,
// and for rentals that need documents licence_file, id_file (private upload ids from /_rx/upload.js; optional here, required before handover)
// Checks availability and prices again from the database, records the reservation, then either sends the customer to pay
// the online share by card (status pending until on_payment confirms it) or confirms it at once as pay-later.
function handle(req) {
  const f = req.form, lang = f.lang === 'ar' ? 'ar' : 'en', ql = lang === 'ar' ? '&lang=ar' : '', b = business();
  const i = db.query('SELECT * FROM items WHERE id = ? AND active = 1', Number(f.item))[0];
  if (!i) return {redirect: '/' + (lang === 'ar' ? '?lang=ar' : '')};
  const back = '/item/' + i.id + '?error=';
  if (!req.user) return {redirect: '/_rx/auth/login?next=' + encodeURIComponent('/item/' + i.id + (lang === 'ar' ? '?lang=ar' : ''))};
  const name = (f.name || '').trim(), phone = (f.phone || '').trim(), notes = (f.notes || '').trim().slice(0, 1000);
  if (!name || !phone) return {redirect: back + 'error_fields' + ql};
  const q = quote(i, f, b, 0);
  if (!q.ok) return {redirect: back + q.error + '&n=' + q.n + ql};
  let method = f.payment === 'card' && q.online > 0 ? 'card' : 'later';
  if (method === 'later' && !b.pay_later_enabled) {
    if (!(q.online > 0)) return {redirect: back + 'error_payment' + ql};
    method = 'card';
  }
  // Documents uploaded at checkout must be the visitor's own files; they can also be added later on the reservation page.
  let licence = null, idFile = null;
  if (q.documents) {
    licence = ownFile(f.licence_file, req.user); idFile = ownFile(f.id_file, req.user);
    if (licence === '' || idFile === '') return {redirect: back + 'error_document' + ql};
  }
  const due = method === 'card' ? q.online : 0;
  const now = new Date().toISOString().replace('T', ' ').slice(0, 19);
  const id = db.exec(`INSERT INTO reservations (user_id, customer_name, phone, email, item_id, item_name, mode, departure_id, start_date, end_date, time, days,
    adults, children, quantity, extras, lines, subtotal, vat, total, due_online, paid_amount, balance_due, security_deposit, payment_method, status, lang, notes,
    pending_since, reminded, deposit_status, deposit_link_sent, documents_required, licence_file, id_file)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?, 0, ?, ?, ?)`,
    req.user.id, name, phone, req.user.email || '', i.id, i.name, i.mode, q.departure_id, q.start, q.end, q.time, q.days,
    q.adults, q.children, q.qty, JSON.stringify(q.extras), JSON.stringify(q.lines), q.net, q.vat, q.total, due, 0, round2(q.total - due), q.security,
    method, method === 'card' ? 'pending' : 'confirmed', lang, notes, now, q.depositHold ? 'due' : null, q.documents ? 1 : 0, licence, idFile).lastInsertId;
  const path = '/reservations/' + id;
  if (method === 'later') {
    const r = db.query('SELECT * FROM reservations WHERE id = ?', id)[0];
    mailCustomer(r, 'email', req.origin);
    tellOwner(r, 'New reservation');
    return {redirect: path + '?placed=1' + ql};
  }
  try {
    const pay = payments.checkout({items: [{name: i.name + ' – reservation #' + id + (due < q.total ? ' (deposit)' : ''), price: due, quantity: 1}],
      reference: 'res-' + id, customer_email: req.user.email || '', success_path: path + '?placed=1' + ql, cancel_path: path + (lang === 'ar' ? '?lang=ar' : '')});
    return {redirect: pay.url};
  } catch (e) {
    console.error('checkout failed for reservation ' + id + ': ' + e);
    db.exec("UPDATE reservations SET status = 'failed' WHERE id = ?", id); // frees the seats or stock
    return {redirect: back + 'error_payment' + ql};
  }
}

