scripts.pay_again:
// POST /reservations/:id/pay (signed in): pay the online share of a reservation whose payment was not completed.
// A failed or expired reservation no longer holds its seats or stock, so availability is checked again first.
function handle(req) {
  const id = Number(req.params.id), b = business();
  const r = db.query('SELECT * FROM reservations WHERE id = ? AND user_id = ?', id, req.user.id)[0];
  if (!r) return {text: 'Not found', status: 404};
  const lang = r.lang === 'ar' ? 'ar' : 'en', path = '/reservations/' + id, ql = lang === 'ar' ? '?lang=ar' : '';
  if (r.payment_method !== 'card' || !(r.due_online > 0) || ['pending', 'failed', 'expired'].indexOf(r.status) < 0 || r.start_date < nowDubai().date) return {redirect: path + ql};
  const item = db.query('SELECT * FROM items WHERE id = ?', r.item_id)[0];
  const left = r.mode === 'departure'
    ? (db.query('SELECT capacity FROM departures WHERE id = ?', r.departure_id)[0] || {capacity: 0}).capacity - seatsTaken(r.departure_id, r.start_date, id)
    : rangeLeft(item || {id: r.item_id, stock: 0}, r.start_date, r.end_date, id);
  const need = r.mode === 'departure' ? r.adults + r.children : r.quantity;
  if (left < need) return {redirect: '/item/' + r.item_id + '?error=' + (r.mode === 'departure' ? 'error_seats' : 'error_stock') + '&n=' + Math.max(0, left) + (lang === 'ar' ? '&lang=ar' : '')};
  db.exec("UPDATE reservations SET status = 'pending', pending_since = ? WHERE id = ?", new Date().toISOString().replace('T', ' ').slice(0, 19), id);
  try {
    const pay = payments.checkout({items: [{name: r.item_name + ' – reservation #' + id + (r.due_online < r.total ? ' (deposit)' : ''), price: r.due_online, quantity: 1}],
      reference: 'res-' + id, customer_email: req.user.email || '', success_path: path + '?placed=1' + (lang === 'ar' ? '&lang=ar' : ''), cancel_path: path + ql});
    return {redirect: pay.url};
  } catch (e) {
    console.error('checkout failed for reservation ' + id + ': ' + e);
    db.exec("UPDATE reservations SET status = 'failed' WHERE id = ?", id);
    return {redirect: path + ql};
  }
}

scripts.cancel:
// POST /reservations/:id/cancel (signed in): the customer cancels inside the free-cancellation window.
// What was paid online is refunded with payments.refund and a deposit hold is released; if the refund fails, the owner is told to make it.
function handle(req) {
  const id = Number(req.params.id), b = business();
  const r = db.query('SELECT * FROM reservations WHERE id = ? AND user_id = ?', id, req.user.id)[0];
  if (!r) return {text: 'Not found', status: 404};
  const ql = r.lang === 'ar' ? '&lang=ar' : '';
  if (!canCancel(r, b)) return {redirect: '/reservations/' + id + (r.lang === 'ar' ? '?lang=ar' : '')};
  db.exec("UPDATE reservations SET status = 'cancelled' WHERE id = ? AND user_id = ?", id, req.user.id); // frees the seats or stock
  r.status = 'cancelled';
  const m = settleCancelled(r, 'requested_by_customer');
  mailCustomer(r, 'cancel', req.origin);
  const what = m.refunded > 0 ? ', refunded AED ' + money(m.refunded) : r.paid_amount > 0 ? ', refund AED ' + money(r.paid_amount) : ', nothing paid';
  try {
    notify.owner({subject: ('Cancelled by customer #' + id + ': ' + r.item_name + ', ' + r.start_date + what).slice(0, 149),
      text: 'Customer: ' + r.customer_name + ', ' + r.phone + '\n' + moneyNote(r, m)});
  } catch (e) { console.warn('owner not notified: ' + e); }
  return {redirect: '/reservations/' + id + '?cancelled=1' + ql};
}

scripts.on_payment:
// Runs when a card payment is paid, fails or expires, when it is refunded (from a script, the admin panel or Stripe), and for the
// deposit hold. req.body: {event, reference, amount, refunded_amount, hold_expires_at, ...}.
// Reference res-<id> is the reservation's own payment; res-<id>-deposit its security deposit hold.
function handle(req) {
  const m = /^res-(\d+)(-deposit)?$/.exec(String(req.body.reference || ''));
  if (!m) return {text: 'ignored'};
  const id = Number(m[1]);
  const r = db.query('SELECT * FROM reservations WHERE id = ?', id)[0];
  if (!r) return {text: 'ignored'};
  if (m[2]) return depositEvent(r, req.body, req.origin);
  const event = req.body.event;
  if (event === 'refunded' || event === 'partially_refunded') {
    // Record what is left of the payment. A full refund also marks the reservation refunded, which frees its seats or stock,
    // and releases a deposit hold still in place.
    const kept = Math.max(0, round2(req.body.amount - req.body.refunded_amount));
    if (event === 'refunded') {
      db.exec("UPDATE reservations SET status = 'refunded', paid_amount = 0, balance_due = 0 WHERE id = ?", id);
      if (r.deposit_status === 'authorized') releaseDeposit(r);
    } else db.exec('UPDATE reservations SET paid_amount = ?, balance_due = ? WHERE id = ?', kept, r.status === 'cancelled' ? 0 : round2(r.total - kept), id);
    console.log('reservation ' + id + ' ' + event + ' ' + req.body.refunded_amount);
    return {text: 'ok'};
  }
  if (event === 'paid') {
    if (r.status === 'confirmed' || r.status === 'completed') return {text: 'ignored'};
    const paid = round2(req.body.amount);
    if (r.status === 'cancelled' || r.status === 'refunded' || r.status === 'no_show') {
      // Money arrived for a reservation that is no longer wanted: keep the record and let the owner refund it.
      db.exec('UPDATE reservations SET paid_amount = ? WHERE id = ?', paid, id);
      try { notify.owner({subject: 'Payment of AED ' + money(paid) + ' for ' + r.status + ' reservation #' + id + ': refund it on the Payments page', text: r.customer_name + ', ' + r.phone}); } catch (e) { console.warn('owner not notified: ' + e); }
      return {text: 'ok'};
    }
    // pending, or failed/expired and paid late after all: the customer has paid, so confirm.
    db.exec("UPDATE reservations SET status = 'confirmed', paid_amount = ?, balance_due = ? WHERE id = ?", paid, Math.max(0, round2(r.total - paid)), id);
    const now = db.query('SELECT * FROM reservations WHERE id = ?', id)[0];
    mailCustomer(now, 'email', req.origin);
    tellOwner(now, r.status === 'pending' ? 'New reservation' : 'Paid late, check availability');
  } else if (r.status === 'pending') {
    // failed or expired: the reservation no longer holds its seats or stock. The customer can pay again from the reservation page.
    db.exec('UPDATE reservations SET status = ? WHERE id = ?', event === 'failed' ? 'failed' : 'expired', id);
  }
  console.log('reservation ' + id + ' payment ' + event);
  return {text: 'ok'};
}

// The deposit hold: authorized (held on the card), paid (the owner captured a damage charge), released (by the owner, by a
// cancellation, or by the card after about 7 days), refunded (a damage charge given back). Failed or expired checkouts leave it due.
function depositEvent(r, p, origin) {
  const event = p.event;
  if (event === 'authorized') {
    if (['cancelled', 'refunded', 'failed', 'expired'].indexOf(r.status) >= 0) {
      releaseDeposit(r); // authorised after the reservation ended: nothing to hold
    } else {
      db.exec("UPDATE reservations SET deposit_status = 'authorized', deposit_expires_at = ? WHERE id = ?", p.hold_expires_at || '', r.id);
      mailCustomer(db.query('SELECT * FROM reservations WHERE id = ?', r.id)[0], 'deposit_held', origin);
    }
  } else if (event === 'paid') {
    db.exec("UPDATE reservations SET deposit_status = 'captured', deposit_captured = ? WHERE id = ?", round2(p.amount), r.id);
  } else if (event === 'refunded' || event === 'partially_refunded') {
    db.exec('UPDATE reservations SET deposit_captured = ? WHERE id = ?', Math.max(0, round2(p.amount - p.refunded_amount)), r.id);
  } else if (event === 'released' && r.deposit_status === 'authorized') {
    // Not released by the app, so the card dropped the hold. The customer can authorise it again from the reservation page.
    db.exec("UPDATE reservations SET deposit_status = 'expired', deposit_link_sent = 0 WHERE id = ?", r.id);
    try {
      notify.owner({subject: ('Deposit hold expired for #' + r.id + ': ' + r.item_name + ', ' + r.start_date + ' to ' + r.end_date + ', AED ' + money(r.security_deposit)).slice(0, 149),
        text: 'The card hold for the security deposit has ended. The customer can authorise it again from the reservation page, or collect the deposit at handover.\n\nCustomer: ' + r.customer_name + ', ' + r.phone});
    } catch (e) { console.warn('owner not notified: ' + e); }
  }
  console.log('reservation ' + r.id + ' deposit ' + event);
  return {text: 'ok'};
}

scripts.mcp_search:
// MCP tool search_items: {query, category, lang}
function handle(req) {
  const a = req.body || {}, lang = a.lang === 'ar' ? 'ar' : 'en';
  const words = String(a.query || '').toLowerCase().split(/\s+/).filter(Boolean), cat = String(a.category || '').toLowerCase();
  const out = [];
  for (const i of db.query('SELECT * FROM items WHERE active = 1 ORDER BY id')) {
    if (cat && (i.category || '').toLowerCase() !== cat && (i.category_ar || '') !== a.category) continue;
    const hay = [i.name, i.name_ar, i.description, i.description_ar, i.category, i.category_ar, i.included].join(' ').toLowerCase();
    if (!words.every(w => hay.indexOf(w) >= 0)) continue;
    const row = {id: i.id, name: loc(i, 'name', lang), category: loc(i, 'category', lang), description: loc(i, 'description', lang),
      kind: i.mode === 'departure' ? 'tour with dated departures' : 'rental by the day', url: req.origin + '/item/' + i.id + (lang === 'ar' ? '?lang=ar' : '')};
    if (i.mode === 'departure') {
      row.price_per_adult = i.price_adult; row.price_per_child = i.price_child === null ? i.price_adult : i.price_child;
      row.duration = loc(i, 'duration', lang) || null;
    } else {
      row.price_per_day = i.price_day; row.price_per_week = i.price_week || null; row.minimum_days = i.min_days || 1;
      row.quantity_owned = i.stock || 0; row.security_deposit_at_handover = i.security_deposit || 0;
    }
    row.included = loc(i, 'included', lang) || null;
    out.push(row);
    if (out.length >= 30) break;
  }
  return {json: {currency: 'AED', prices_include_vat: true, items: out}};
}

scripts.mcp_availability:
// MCP tool check_availability: {item, date, start, end, people, children, quantity, lang}
// Tours: the departures on date (or the next ones) with seats left and the price for the party.
// Rentals: units free from start to end and the price for that many days.
function handle(req) {
  const a = req.body || {}, lang = a.lang === 'ar' ? 'ar' : 'en', t = texts(lang), b = business();
  const i = db.query('SELECT * FROM items WHERE id = ? AND active = 1', Number(a.item))[0];
  if (!i) return {text: 'No such item; use search_items to find item ids.', status: 404};
  const url = req.origin + '/item/' + i.id + (lang === 'ar' ? '?lang=ar' : '');
  if (i.mode === 'departure') {
    const adults = whole(a.people, 1), children = whole(a.children, 0);
    let list = occurrences(i, b, lang, 400);
    if (a.date) list = list.filter(o => o.date === String(a.date));
    const departures = list.slice(0, 10).map(o => {
      const q = quote(i, {when: o.key, adults: String(adults), children: String(children)}, b, 0);
      return {date: o.date, time: o.time, seats_left: o.left, available: q.ok, price_per_adult: o.priceNum, total_price: q.ok ? q.total : null,
        pay_online_now: q.ok ? q.online : null};
    });
    return {json: {item: loc(i, 'name', lang), kind: 'tour', adults: adults, children: children, available: departures.some(d => d.available), departures: departures,
      currency: 'AED', prices_include_vat: true, note: departures.length ? 'Extras such as hotel pickup are chosen on the booking page.' : 'No departure on that date within the bookable period.',
      book_at: url}};
  }
  if (!a.start || !a.end) return {text: 'For a rental give start and end as YYYY-MM-DD.', status: 400};
  const q = quote(i, {start: String(a.start), end: String(a.end), qty: String(whole(a.quantity, 1))}, b, 0);
  const out = {item: loc(i, 'name', lang), kind: 'rental', start: String(a.start), end: String(a.end), quantity: whole(a.quantity, 1), available: q.ok,
    stock_left: q.ok ? q.left : q.n, currency: 'AED', prices_include_vat: true, book_at: url};
  if (q.ok) {
    out.days = q.days; out.total_price = q.total; out.pay_online_now = q.online; out.security_deposit_at_handover = q.depositHold ? 0 : q.security;
    out.security_deposit_card_hold = q.depositHold ? q.security : 0; out.documents_required = q.documents;
  } else {
    out.reason = errorText(t, q.error, q.n);
  }
  return {json: out};
}

scripts.mcp_business:
// MCP tool business_info: who we are, how payment and cancellation work, contact.
