scripts.daily:
// Job, every evening: expire reservations left unpaid, email the owner tomorrow's departures (with passenger counts),
// handovers (deposit and documents) and returns, remind tomorrow's customers by email, and email the link to authorise the
// deposit hold to customers whose rental starts within HOLD_DAYS.
function handle(req) {
  const tomorrow = addDays(nowDubai().date, 1);
  // 1. A card reservation still waiting for payment after two hours stops holding its seats or stock.
  const cutoff = new Date(Date.now() - 2 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);
  const expired = db.exec("UPDATE reservations SET status = 'expired' WHERE status = 'pending' AND COALESCE(pending_since, created_at) < ?", cutoff).rowsAffected;

  // 2. Tomorrow for the owner.
  const who = (r) => '  #' + r.id + ' ' + r.customer_name + ', ' + r.phone + (r.balance_due > 0 ? ', balance AED ' + money(r.balance_due) : ', paid') + (r.notes ? ' (' + r.notes + ')' : '');
  const out = db.query(`SELECT * FROM reservations WHERE start_date = ? AND status = 'confirmed' ORDER BY mode, time, item_name, id LIMIT 300`, tomorrow);
  const back = db.query(`SELECT * FROM reservations WHERE mode = 'range' AND end_date = ? AND status = 'confirmed' ORDER BY item_name, id LIMIT 300`, tomorrow);
  const trips = {}, order = [];
  let passengers = 0, handovers = 0;
  const handoverLines = [];
  for (const r of out) {
    if (r.mode === 'departure') {
      const key = r.time + ' ' + r.item_name;
      if (!trips[key]) { trips[key] = {pax: 0, lines: []}; order.push(key); }
      trips[key].pax += r.adults + r.children;
      trips[key].lines.push(who(r) + ': ' + r.adults + ' adults' + (r.children ? ', ' + r.children + ' children' : ''));
      passengers += r.adults + r.children;
    } else {
      handovers++;
      handoverLines.push(r.quantity + ' x ' + r.item_name + ' until ' + r.end_date + depositNote(r) +
        (r.documents_required ? (documentsReceived(r) ? ', documents received' : ', documents NOT uploaded: check licence and passport') : '') + '\n' + who(r));
    }
  }
  const summary = order.length + ' departure' + (order.length === 1 ? '' : 's') + ' (' + passengers + ' passenger' + (passengers === 1 ? '' : 's') + '), ' +
    handovers + ' handover' + (handovers === 1 ? '' : 's') + ', ' + back.length + ' return' + (back.length === 1 ? '' : 's');
  if (out.length || back.length) {
    let text = '';
    if (order.length) text += 'DEPARTURES\n' + order.map(k => k + ': ' + trips[k].pax + ' passengers\n' + trips[k].lines.join('\n')).join('\n\n') + '\n\n';
    if (handovers) text += 'HANDOVERS\n' + handoverLines.join('\n') + '\n\n';
    if (back.length) text += 'RETURNS\n' + back.map(r => r.quantity + ' x ' + r.item_name + ' since ' + r.start_date +
      (r.deposit_status === 'authorized' ? ', deposit AED ' + money(r.security_deposit) + ' held: set Deposit at return to release or capture' : '') + '\n' + who(r)).join('\n') + '\n';
    try { notify.owner({subject: 'Tomorrow ' + tomorrow + ': ' + summary, text: text}); } catch (e) { console.warn('owner not notified: ' + e); }
  }

  // 3. Remind tomorrow's customers once. At most 40 a run, to stay inside the limits of one script.
  let reminded = 0;
  for (const r of out) {
    if (r.reminded || !r.email || reminded >= 40) continue;
    if (mailCustomer(r, 'remind', req.origin)) reminded++;
    db.exec('UPDATE reservations SET reminded = 1 WHERE id = ?', r.id);
  }

  // 4. The deposit hold link, once, when a rental comes within HOLD_DAYS of its start (holds last about 7 days).
  const today = nowDubai().date;
  let links = 0;
  for (const r of db.query(`SELECT * FROM reservations WHERE status = 'confirmed' AND deposit_status IN ('due', 'expired') AND COALESCE(deposit_link_sent, 0) = 0
    AND start_date >= ? AND start_date <= ? ORDER BY start_date, id LIMIT 40`, today, addDays(today, HOLD_DAYS))) {
    if (r.email && mailCustomer(r, 'deposit', req.origin)) links++;
    else db.exec('UPDATE reservations SET deposit_link_sent = 1 WHERE id = ?', r.id);
  }
  return {text: 'tomorrow ' + tomorrow + ': ' + summary + '; ' + reminded + ' reminded; ' + expired + ' expired; ' + links + ' deposit link' + (links === 1 ? '' : 's')};
}
function depositNote(r) {
  if (!(r.security_deposit > 0)) return '';
  if (!r.deposit_status) return ', collect deposit AED ' + money(r.security_deposit);
  if (r.deposit_status === 'authorized') return ', deposit AED ' + money(r.security_deposit) + ' held on the card';
  return ', deposit AED ' + money(r.security_deposit) + ' NOT authorised: collect it at handover';
}

scripts.admin_change:
// on_admin_change: runs right after the owner or staff changes a reservation in the admin panel.
// - status set to cancelled: refunds what was paid online, releases the deposit hold and emails the customer;
// - status set to confirmed (e.g. a reservation taken by phone), or no_show: emails the customer;
// - dates, time or departure changed: emails the customer, and the reminder and the deposit link go out again;
// - deposit_action set to release, or to capture with damage_amount, while the deposit is held: releases the hold or takes the
//   damage charge (the rest is released), and emails the customer.
function handle(req) {
  const b = req.body;
  if (b.table !== 'reservations' || b.action === 'delete' || !b.row) return {text: 'nothing to do'};
  const r = b.row, was = b.before || {}, done = [];
  const s = (v) => v === null || v === undefined ? '' : String(v);
  const became = (status) => r.status === status && s(was.status) !== status;

  if (became('cancelled') && s(was.status) !== 'refunded') {
    const m = settleCancelled(r, 'cancelled by the business');
    mailCustomer(r, 'cancel', req.origin);
    if (m.refundFailed || m.releaseFailed) notifyOwner('Reservation #' + r.id + ' cancelled: refund or deposit release not made', moneyNote(r, m));
    return {text: 'cancelled' + (m.refunded > 0 ? ', refunded ' + money(m.refunded) : '') + (m.released ? ', deposit released' : '') + ', customer emailed'};
  }
  if (became('confirmed') && mailCustomer(r, 'email', req.origin)) done.push('confirmation emailed');
  if (became('no_show') && mailCustomer(r, 'no_show', req.origin)) done.push('no-show emailed');
  if (b.action === 'update' && (r.status === 'pending' || r.status === 'confirmed') && !became('confirmed') &&
    ['start_date', 'end_date', 'time', 'departure_id'].some(k => s(was[k]) !== s(r[k]))) {
    db.exec('UPDATE reservations SET reminded = 0, deposit_link_sent = 0 WHERE id = ?', r.id);
    r.reminded = 0;
    r.deposit_link_sent = 0;
    if (mailCustomer(r, 'changed', req.origin)) done.push('change emailed');
  }

  if (r.deposit_status === 'authorized' && (r.deposit_action === 'release' || r.deposit_action === 'capture')) {
    const damage = round2(Number(r.damage_amount) || 0);
    if (r.deposit_action === 'capture' && damage > 0) {
      if (damage > r.security_deposit) {
        notifyOwner('Damage charge for #' + r.id + ' not taken: AED ' + money(damage) + ' is more than the deposit of AED ' + money(r.security_deposit),
          'Change the damage charge and save again.');
        done.push('damage charge is more than the deposit');
      } else {
        try {
          const res = payments.capture({reference: depositRef(r), amount: damage});
          db.exec("UPDATE reservations SET deposit_status = 'captured', deposit_captured = ? WHERE id = ?", round2(res.amount), r.id);
          r.deposit_status = 'captured';
          r.deposit_captured = round2(res.amount);
          mailCustomer(r, 'deposit_captured', req.origin);
          done.push('captured ' + money(res.amount) + ' of the deposit');
        } catch (e) {
          console.warn('deposit of reservation ' + r.id + ' not captured: ' + e);
          notifyOwner('Damage charge for #' + r.id + ' not taken', String(e));
          done.push('capture failed');
        }
      }
    } else if (releaseDeposit(r)) {
      r.deposit_status = 'released';
      mailCustomer(r, 'deposit_released', req.origin);
      done.push('deposit released');
    } else {
      notifyOwner('Deposit hold for #' + r.id + ' not released', 'Release it on the Payments page of the admin panel.');
      done.push('release failed');
    }
  }
  return {text: done.join('; ') || 'nothing to do'};
}
function notifyOwner(subject, text) {
  try { notify.owner({subject: subject.slice(0, 149), text: text}); } catch (e) { console.warn('owner not notified: ' + e); }
}

scripts.deposit:
// POST /reservations/:id/deposit (signed in): the customer authorises the refundable security deposit as a card hold, from
// HOLD_DAYS before the start. Nothing is charged; on_payment records the hold, and the owner releases or captures it at the return.
function handle(req) {
  const id = Number(req.params.id);
  const r = db.query('SELECT * FROM reservations WHERE id = ? AND user_id = ?', id, req.user.id)[0];
  if (!r) return {text: 'Not found', status: 404};
  const lang = r.lang === 'ar' ? 'ar' : 'en', path = '/reservations/' + id, ql = lang === 'ar' ? '?lang=ar' : '';
  if (!depositOpen(r)) return {redirect: path + ql};
  try {
    const pay = payments.checkout({items: [{name: r.item_name + ' – security deposit, reservation #' + id, price: r.security_deposit, quantity: 1}], hold: true,
      reference: depositRef(r), customer_email: req.user.email || r.email || '', success_path: path + '?deposit=1' + (lang === 'ar' ? '&lang=ar' : ''), cancel_path: path + ql});
    return {redirect: pay.url};
  } catch (e) {
    console.error('deposit hold not started for reservation ' + id + ': ' + e);
    return {redirect: path + '?error=error_payment' + (lang === 'ar' ? '&lang=ar' : '')};
  }
}

scripts.documents:
// POST /reservations/:id/documents (signed in)  form: licence_file, id_file (private upload ids from /_rx/upload.js; one or both)
// The customer's driving licence and passport or Emirates ID before handover. Each id must be a file this visitor uploaded.
function handle(req) {
  const id = Number(req.params.id);
  const r = db.query('SELECT * FROM reservations WHERE id = ? AND user_id = ?', id, req.user.id)[0];
  if (!r) return {text: 'Not found', status: 404};
  const path = '/reservations/' + id, ql = r.lang === 'ar' ? '&lang=ar' : '';
  if (!canUpload(r)) return {redirect: path + (r.lang === 'ar' ? '?lang=ar' : '')};
  const licence = ownFile(req.form.licence_file, req.user), idFile = ownFile(req.form.id_file, req.user);
  if (licence === '' || idFile === '' || (!licence && !idFile)) return {redirect: path + '?error=error_document' + ql};
  db.exec('UPDATE reservations SET licence_file = COALESCE(?, licence_file), id_file = COALESCE(?, id_file) WHERE id = ? AND user_id = ?', licence, idFile, id, req.user.id);
  const now = db.query('SELECT * FROM reservations WHERE id = ?', id)[0];
  if (documentsReceived(now) && !documentsReceived(r)) {
    try {
      notify.owner({subject: ('Documents received for #' + id + ': ' + r.item_name + ', ' + r.start_date + ', ' + r.customer_name).slice(0, 149),
        text: 'The driving licence and the passport or Emirates ID are uploaded. Open them from the reservation in the admin panel.'});
    } catch (e) { console.warn('owner not notified: ' + e); }
  }
  return {redirect: path + '?docs=1' + ql};
}

lib.a_common:
// Helpers shared by every script (lib entries run in name order before each script, job, tool and hook): texts, settings, money, UAE dates, page data.
function langOf(req) { return req.query.lang === 'ar' ? 'ar' : 'en'; }
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function business() { return db.query('SELECT * FROM business ORDER BY id LIMIT 1')[0]; }
function round2(n) { return Math.round(n * 100) / 100; }
function money(n) { return round2(n || 0).toFixed(2); }
function loc(row, field, lang) { return lang === 'ar' && row[field + '_ar'] ? row[field + '_ar'] : row[field]; }

// Dates are local UAE dates as text, 'YYYY-MM-DD', and times 'HH:MM'; they compare correctly as strings.
// The UAE is UTC+4 all year, so "now" in Dubai is UTC plus four hours.
function nowDubai() {
  const iso = new Date(Date.now() + 4 * 3600 * 1000).toISOString();
  return {date: iso.slice(0, 10), time: iso.slice(11, 16)};
}
// Milliseconds (UTC midnight) of a 'YYYY-MM-DD' date, or null when it is not a real date.
function parts(s) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
  if (!m) return null;
  const ms = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return new Date(ms).toISOString().slice(0, 10) === s ? ms : null;
}
function addDays(s, n) { return new Date(parts(s) + n * 86400000).toISOString().slice(0, 10); }
function dayDiff(a, b) { return Math.round((parts(b) - parts(a)) / 86400000); }
const WEEKDAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const DAY_NAMES = {en: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], ar: ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت']};
const MONTH_NAMES = {en: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
  ar: ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر']};
function showDate(s, lang) {
  const ms = parts(s);
  if (ms === null) return s || '';
  const d = new Date(ms), l = lang === 'ar' ? 'ar' : 'en';
  return DAY_NAMES[l][d.getUTCDay()] + ' ' + d.getUTCDate() + ' ' + MONTH_NAMES[l][d.getUTCMonth()] + ' ' + d.getUTCFullYear();
}
// A whole number from a form or query value; def when it is missing, -1 when it is not a whole number.
function whole(v, def) {
  if (v === undefined || v === null || v === '') return def;
  const n = Number(v);
  return Number.isInteger(n) ? n : -1;
}
function errorText(t, key, n) { return (t[key] || t.error_departure).replace(/\{n\}/g, String(n || 0)); }
function lineLabel(l, lang) { return (lang === 'ar' && l.name_ar ? l.name_ar : l.name) + (l.qty > 1 ? ' × ' + l.qty : ''); }

function page(req, extra) {
  const lang = langOf(req), b = business(), qs = [];
  for (const k in req.query) if (k !== 'lang' && k !== 'error' && k !== 'n') qs.push(encodeURIComponent(k) + '=' + encodeURIComponent(req.query[k]));
  const mine = qs.concat(lang === 'ar' ? ['lang=ar'] : []);
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', t: texts(lang), user: req.user, business: b,
    businessName: loc(b, 'name', lang), tagline: loc(b, 'tagline', lang), licence: b.licence || '',
    here: req.path + (mine.length ? '?' + mine.join('&') : ''),
    langUrl: req.path + '?' + qs.concat(['lang=' + (lang === 'ar' ? 'en' : 'ar')]).join('&'),
    wa: (b.whatsapp || '').replace(/[^0-9]/g, '')};
  for (const k in extra) base[k] = extra[k];
  return base;
}

lib.b_inventory:
// Inventory and prices: departures, seats and stock added up from the reservations, rental prices, extras, quotes.
// A departure row runs on its own date, or, when date is empty, on its weekdays ('daily' or e.g. 'fri,sat').
function runsOn(dep, date) {
  if (dep.date) return dep.date === date;
  const w = (dep.weekdays || 'daily').toLowerCase();
  return w.indexOf('daily') >= 0 || w.indexOf(WEEKDAYS[new Date(parts(date)).getUTCDay()]) >= 0;
}
// Nothing is counted down: seats and stock in use are added up from the reservations that hold them
// (pending, confirmed, completed, no_show), so a cancelled, failed, expired or refunded reservation frees them by itself.
function seatsTaken(depId, date, exceptId) {
  return db.query(`SELECT COALESCE(SUM(adults + children), 0) AS n FROM reservations WHERE departure_id = ? AND start_date = ? AND id <> ?
    AND status IN ('pending', 'confirmed', 'completed', 'no_show')`, depId, date, exceptId || 0)[0].n;
}
// Units of a rental item free on every day from start to end: stock minus the busiest day in that range.
// The return day counts as taken.
function rangeLeft(item, start, end, exceptId) {
  const rows = db.query(`SELECT start_date, end_date, quantity FROM reservations WHERE item_id = ? AND mode = 'range' AND id <> ?
    AND start_date <= ? AND end_date >= ? AND status IN ('pending', 'confirmed', 'completed', 'no_show')`, item.id, exceptId || 0, end, start);
  let busiest = 0;
  for (let d = start; d <= end; d = addDays(d, 1)) {
    let n = 0;
    for (const r of rows) if (r.start_date <= d && r.end_date >= d) n += r.quantity;
    if (n > busiest) busiest = n;
  }
  return (item.stock || 0) - busiest;
}
// Price of one unit for a number of days: full weeks at the weekly price when there is one, never more than one more full week.
function rentalPrice(item, days) {
  const day = item.price_day || 0;
  if (!item.price_week) return day * days;
  const weeks = Math.floor(days / 7);
  return Math.min(weeks * item.price_week + (days % 7) * day, (weeks + 1) * item.price_week);
}
// Rentals of cars (category Cars) or of items with needs_documents ask for a driving licence and a passport, uploaded privately.
function needsDocuments(item) { return !!item.needs_documents || (item.mode === 'range' && /^cars?$/i.test((item.category || '').trim())); }
function extrasFor(item) {
  return db.query(`SELECT * FROM extras WHERE active = 1 AND (item_id = ? OR (item_id IS NULL AND (category = ? OR category IS NULL OR category = ''))) ORDER BY id`,
    item.id, item.category || '');
}
// Upcoming departures of a tour within the bookable period, with seats left.
function occurrences(item, b, lang, limit) {
  const now = nowDubai(), ahead = b.days_ahead > 0 ? b.days_ahead : 60;
  const deps = db.query('SELECT * FROM departures WHERE item_id = ? AND active = 1 ORDER BY time, id', item.id);
  const taken = {};
  for (const r of db.query(`SELECT departure_id, start_date, SUM(adults + children) AS n FROM reservations WHERE item_id = ? AND mode = 'departure'
    AND start_date >= ? AND status IN ('pending', 'confirmed', 'completed', 'no_show') GROUP BY departure_id, start_date`, item.id, now.date)) {
    taken[r.departure_id + '_' + r.start_date] = r.n;
  }
  const out = [];
  for (let i = 0; i <= ahead && out.length < limit; i++) {
    const date = addDays(now.date, i);
    for (const d of deps) {
      if (!runsOn(d, date) || (i === 0 && d.time <= now.time)) continue;
      const key = d.id + '_' + date, left = d.capacity - (taken[key] || 0);
      out.push({key: key, departure_id: d.id, date: date, time: d.time, label: showDate(date, lang) + ' · ' + d.time, left: left, full: left <= 0,
        priceNum: d.price === null ? item.price_adult : d.price, price: money(d.price === null ? item.price_adult : d.price)});
    }
  }
  return out;
}

// Checks one request against the database and prices it. f holds strings as sent by the browser:
// tours: when ('<departure id>_<date>'), adults, children; rentals: start, end, qty; extras: x<extra id> = '1'.
// Returns {ok: true, lines, total, vat, online, ...} or {ok: false, error: '<texts key>', n}. Prices never come from the browser.
function quote(item, f, b, exceptId) {
  const now = nowDubai(), ahead = b.days_ahead > 0 ? b.days_ahead : 60, last = addDays(now.date, ahead);
  const en = texts('en'), ar = texts('ar');
  const q = {ok: false, complete: true, error: '', n: 0, mode: item.mode, left: 0, departure_id: null, start: '', end: '', time: '', days: 1,
    adults: 0, children: 0, qty: 1, lines: [], extras: []};
  const fail = (key, n) => { q.error = key; q.n = n || 0; return q; };
  let people = 0;
  if (item.mode === 'departure') {
    const m = /^(\d+)_(\d{4}-\d{2}-\d{2})$/.exec(f.when || '');
    if (!m) { q.complete = false; return fail('error_choose_departure'); }
    const dep = db.query('SELECT * FROM departures WHERE id = ? AND item_id = ? AND active = 1', Number(m[1]), item.id)[0];
    const date = m[2];
    if (!dep || parts(date) === null || !runsOn(dep, date) || date < now.date || date > last || (date === now.date && dep.time <= now.time)) return fail('error_departure');
    q.adults = whole(f.adults, 1); q.children = whole(f.children, 0);
    if (!(q.adults >= 1 && q.adults <= 99 && q.children >= 0 && q.children <= 99)) return fail('error_people');
    people = q.adults + q.children;
    q.departure_id = dep.id; q.start = date; q.end = date; q.time = dep.time;
    q.left = dep.capacity - seatsTaken(dep.id, date, exceptId);
    if (q.left < people) return fail('error_seats', Math.max(0, q.left));
    const adult = dep.price === null ? (item.price_adult || 0) : dep.price;
    const child = item.price_child === null ? adult : Math.min(item.price_child, adult);
    q.lines.push({name: item.name + ' – ' + en.adult, name_ar: (item.name_ar || item.name) + ' – ' + ar.adult, qty: q.adults, unit: adult, amount: round2(adult * q.adults)});
    if (q.children > 0) q.lines.push({name: item.name + ' – ' + en.child, name_ar: (item.name_ar || item.name) + ' – ' + ar.child, qty: q.children, unit: child, amount: round2(child * q.children)});
  } else {
    q.start = f.start || ''; q.end = f.end || '';
    if (!q.start || !q.end) { q.complete = false; return fail('error_dates'); }
    if (parts(q.start) === null || parts(q.end) === null || q.start < now.date || q.start > last || q.end < q.start) return fail('error_dates');
    q.days = Math.max(1, dayDiff(q.start, q.end)); // same-day return counts as one day
    if (q.days > 90) return fail('error_dates');
    if (q.days < (item.min_days || 1)) return fail('error_min_days', item.min_days);
    q.qty = whole(f.qty, 1);
    if (!(q.qty >= 1 && q.qty <= 999)) return fail('error_quantity');
    q.left = rangeLeft(item, q.start, q.end, exceptId);
    if (q.left < q.qty) return fail('error_stock', Math.max(0, q.left));
    const unit = rentalPrice(item, q.days);
    const d = ' – ' + q.days + ' ';
    q.lines.push({name: item.name + d + (q.days === 1 ? en.day : en.days), name_ar: (item.name_ar || item.name) + d + (q.days === 1 ? ar.day : ar.days),
      qty: q.qty, unit: unit, amount: round2(unit * q.qty)});
  }
  for (const x of extrasFor(item)) {
    if (f['x' + x.id] !== '1') continue;
    const times = x.per === 'person' ? (item.mode === 'departure' ? people : q.qty) : x.per === 'day' ? q.days : 1;
    q.extras.push(x.id);
    q.lines.push({name: x.name, name_ar: x.name_ar || x.name, qty: times, unit: x.price, amount: round2(x.price * times)});
  }
  let total = 0;
  for (const l of q.lines) total += l.amount;
  q.total = round2(total);
  q.vat = round2(q.total * 5 / 105); // prices include 5% VAT
  q.net = round2(q.total - q.vat);
  const percent = Math.max(0, Math.min(100, b.deposit_percent || 0));
  q.online = b.card_enabled && percent > 0 ? round2(q.total * percent / 100) : 0; // the share paid by card to secure the reservation
  // Refundable, never paid online: a card hold the customer authorises before the start when business.deposit_hold_enabled,
  // else collected at handover.
  q.security = item.mode === 'range' ? round2((item.security_deposit || 0) * q.qty) : 0;
  q.depositHold = q.security > 0 && !!b.deposit_hold_enabled;
  q.documents = needsDocuments(item);
  q.ok = true;
  return q;
}
// Rows of a price summary for the item page (live, through /api/availability) and the checkout page.
function quoteRows(q, t, lang, pay) {
  const rows = q.lines.map(l => ({label: lineLabel(l, lang), value: 'AED ' + money(l.amount), cls: ''}));
  rows.push({label: t.total, value: 'AED ' + money(q.total), cls: 'total'});
  rows.push({label: t.vat_in_total, value: 'AED ' + money(q.vat), cls: 'muted'});
  if (pay && q.online > 0) {
    rows.push({label: t.pay_now, value: 'AED ' + money(q.online), cls: ''});
    rows.push({label: t.balance, value: 'AED ' + money(q.total - q.online), cls: ''});
  }
  if (q.security > 0) rows.push({label: q.depositHold ? t.security_deposit_hold : t.security_deposit, value: 'AED ' + money(q.security), cls: 'muted'});
  return rows;
}

lib.c_reservations:
// A reservation as the customer sees it: when, who, the free-cancellation deadline and the page and voucher data.
function whenText(r, lang, t) {
  if (r.mode === 'departure') return showDate(r.start_date, lang) + ', ' + r.time;
  return showDate(r.start_date, lang) + ' – ' + showDate(r.end_date, lang) + ' (' + r.days + ' ' + (r.days === 1 ? t.day : t.days) + ')';
}
function guestsText(r, t) {
  if (r.mode === 'departure') return t.adults + ': ' + r.adults + (r.children > 0 ? ', ' + t.children + ': ' + r.children : '');
  return t.quantity + ': ' + r.quantity;
}
// The last moment a customer may cancel on the site, as UTC milliseconds: the start (UAE time) minus the free-cancellation hours.
function cancelDeadline(r, b) {
  const hm = r.mode === 'departure' && /^\d{2}:\d{2}$/.test(r.time || '') ? r.time.split(':') : ['00', '00'];
  return parts(r.start_date) + (Number(hm[0]) * 60 + Number(hm[1])) * 60000 - 4 * 3600 * 1000 - (b.free_cancel_hours || 0) * 3600 * 1000;
}
function canCancel(r, b) { return (r.status === 'pending' || r.status === 'confirmed') && Date.now() < cancelDeadline(r, b); }
function deadlineText(r, b, lang) {
  const iso = new Date(cancelDeadline(r, b) + 4 * 3600 * 1000).toISOString();
  return showDate(iso.slice(0, 10), lang) + ', ' + iso.slice(11, 16);
}
// The security deposit of a rental as a card hold (deposit_status: due, authorized, released, captured or expired; empty when it is
// collected at handover). Cards drop a hold after about 7 days, so the customer authorises it only from HOLD_DAYS before the start;
// the daily job emails the link when that day comes.
const HOLD_DAYS = 6;
function depositRef(r) { return 'res-' + r.id + '-deposit'; }
function depositOpen(r) {
  const today = nowDubai().date;
  return (r.deposit_status === 'due' || r.deposit_status === 'expired') && r.status === 'confirmed' && r.security_deposit > 0 &&
    (r.end_date || r.start_date) >= today && dayDiff(today, r.start_date) <= HOLD_DAYS;
}
function depositLater(r) {
  return r.deposit_status === 'due' && (r.status === 'pending' || r.status === 'confirmed') && dayDiff(nowDubai().date, r.start_date) > HOLD_DAYS;
}
function depositText(r, t, lang) {
  if (!r.deposit_status) return '';
  const until = r.deposit_expires_at ? showDate(r.deposit_expires_at.slice(0, 10), lang) : '';
  return (t['deposit_status_' + r.deposit_status] || r.deposit_status).replace(/\{damage\}/g, money(r.deposit_captured)).replace(/\{until\}/g, until);
}
// Driving licence and passport: private uploads (file columns), required on rentals that need documents.
function documentsReceived(r) { return !!(r.licence_file && r.id_file); }
function canUpload(r) { return !!r.documents_required && (r.status === 'pending' || r.status === 'confirmed') && (r.end_date || r.start_date) >= nowDubai().date; }
// A private upload id sent by a form, checked against the visitor: null when none was sent, '' when it is not the visitor's own file.
function ownFile(id, user) {
  if (!id) return null;
  const f = files.get(String(id));
  return f && user && f.user_id === user.id ? f.id : '';
}

// What the reservation page and the voucher show.
function view(r, lang, t, b) {
  const item = db.query('SELECT name, name_ar FROM items WHERE id = ?', r.item_id)[0] || {name: r.item_name};
  return {id: r.id, item: loc(item, 'name', lang), itemId: r.item_id, when: whenText(r, lang, t), guests: guestsText(r, t), date: r.created_at.slice(0, 10),
    status: r.status, statusText: t['status_' + r.status] || r.status, name: r.customer_name, phone: r.phone, email: r.email, notes: r.notes,
    lines: JSON.parse(r.lines || '[]').map(l => ({label: lineLabel(l, lang), amount: money(l.amount)})),
    net: money(r.subtotal), vat: money(r.vat), total: money(r.total), paid: money(r.paid_amount), balance: money(r.balance_due),
    security: r.security_deposit > 0 ? money(r.security_deposit) : '', card: r.payment_method === 'card',
    securityLabel: r.deposit_status ? t.security_deposit_hold : t.security_deposit,
    depositHold: !!r.deposit_status && r.security_deposit > 0, depositStatus: r.deposit_status || '', depositText: depositText(r, t, lang),
    depositOpen: depositOpen(r), depositLater: depositLater(r),
    docsRequired: !!r.documents_required, docsReceived: documentsReceived(r), canUpload: canUpload(r),
    licenceUrl: r.licence_file ? files.url(r.licence_file) || '' : '', idUrl: r.id_file ? files.url(r.id_file) || '' : '',
    canCancel: canCancel(r, b), cancelUntil: deadlineText(r, b, lang), open: r.status === 'pending' || r.status === 'confirmed',
    canPay: r.payment_method === 'card' && (r.status === 'pending' || r.status === 'failed' || r.status === 'expired') && r.due_online > 0 && r.start_date >= nowDubai().date};
}

lib.d_notify:
// Emails to the customer and notices to the owner.
// The deposit line of the confirmation and reminder emails: collected at handover, or a card hold to authorise now or later.
function depositLine(r, t, page) {
  if (!(r.security_deposit > 0)) return '';
  const amount = money(r.security_deposit);
  if (!r.deposit_status) return t.email_deposit.replace(/\{amount\}/g, amount) + '\n';
  if (r.deposit_status === 'authorized') return t.email_deposit_held.replace(/\{amount\}/g, amount) + '\n';
  if (depositOpen(r)) return t.email_deposit_now.replace(/\{amount\}/g, amount).replace(/\{page\}/g, page) + '\n';
  if (depositLater(r)) return t.email_deposit_later.replace(/\{amount\}/g, amount) + '\n';
  return '';
}
// Emails the customer in the reservation's language. kind picks the <kind>_subject and <kind>_body texts: 'email' (confirmation
// and voucher), 'remind', 'cancel', 'changed', 'no_show', 'deposit' (link to authorise the deposit hold), 'deposit_held',
// 'deposit_released' or 'deposit_captured'. A confirmation or reminder that carries the deposit link marks it sent. Quiet on failure.
function mailCustomer(r, kind, origin) {
  if (!r.email) return false;
  const lang = r.lang === 'ar' ? 'ar' : 'en', t = texts(lang), b = business();
  const item = db.query('SELECT name, name_ar FROM items WHERE id = ?', r.item_id)[0] || {name: r.item_name};
  const page = origin + '/reservations/' + r.id + (lang === 'ar' ? '?lang=ar' : '');
  const v = {id: r.id, name: r.customer_name, business: loc(b, 'name', lang), item: loc(item, 'name', lang), when: whenText(r, lang, t), guests: guestsText(r, t),
    total: money(r.total), paid: money(r.paid_amount), balance: money(r.balance_due), whatsapp: b.whatsapp ? 'WhatsApp: ' + b.whatsapp : '',
    link: origin + '/reservations/' + r.id + '/voucher' + (lang === 'ar' ? '?lang=ar' : ''), page: page,
    security: money(r.security_deposit), damage: money(r.deposit_captured),
    deposit: depositLine(r, t, page),
    documents: r.documents_required && !documentsReceived(r) && canUpload(r) ? t.email_documents.replace(/\{page\}/g, page) + '\n' : '',
    cancel: canCancel(r, b) ? t.email_cancel.replace(/\{until\}/g, deadlineText(r, b, lang)) + '\n' : ''};
  const fill = (s) => (s || '').replace(/\{(\w+)\}/g, (m, k) => v[k] === undefined ? m : String(v[k]));
  try {
    email.send({to: r.email, subject: fill(t[kind + '_subject']), text: fill(t[kind + '_body'])});
  } catch (e) { console.warn(kind + ' email not sent: ' + e); return false; }
  if (kind === 'deposit' || ((kind === 'email' || kind === 'remind') && depositOpen(r))) db.exec('UPDATE reservations SET deposit_link_sent = 1 WHERE id = ?', r.id);
  return true;
}
// Tells the owner about a reservation; the subject carries the essentials because it may also go to WhatsApp.
function tellOwner(r, what) {
  const en = texts('en');
  const size = r.mode === 'departure' ? (r.adults + r.children) + ' pax' : r.quantity + ' x ' + r.days + 'd';
  const when = r.mode === 'departure' ? r.start_date + ' ' + r.time : r.start_date + ' to ' + r.end_date;
  const pay = r.payment_method === 'card' ? 'card, AED ' + money(r.paid_amount) + ' paid' : 'pay later';
  try {
    notify.owner({subject: (what + ' #' + r.id + ': ' + r.item_name + ', ' + when + ', ' + size + ', AED ' + money(r.total) + ' (' + pay + ')').slice(0, 149),
      text: JSON.parse(r.lines || '[]').map(l => lineLabel(l, 'en') + ': AED ' + money(l.amount)).join('\n') +
        '\n\nTotal: AED ' + money(r.total) + '\nPaid online: AED ' + money(r.paid_amount) + '\nBalance due on the day: AED ' + money(r.balance_due) +
        (r.security_deposit > 0 ? '\nSecurity deposit: AED ' + money(r.security_deposit) + (r.deposit_status ? ' (card hold, ' + r.deposit_status + ')' : ' at handover') : '') +
        (r.documents_required ? '\nDriving licence and passport: ' + (documentsReceived(r) ? 'received' : 'not uploaded yet') : '') +
        '\n\nCustomer: ' + r.customer_name + ', ' + r.phone + (r.email ? ', ' + r.email : '') + '\n' + guestsText(r, en) + (r.notes ? '\nNotes: ' + r.notes : '')});
  } catch (e) { console.warn('owner not notified: ' + e); }
}

lib.e_money:
// Money after a cancellation: refund what was paid online and release the deposit hold. Both are recorded here at once;
// on_payment then records the same again, which changes nothing.
// Returns {refunded (AED), refundFailed, released, releaseFailed}. reason goes to Stripe with the refund.
function settleCancelled(r, reason) {
  const out = {refunded: 0, refundFailed: false, released: false, releaseFailed: false};
  if (r.paid_amount > 0) {
    try {
      const res = payments.refund({reference: 'res-' + r.id, reason: reason});
      const kept = Math.max(0, round2(res.amount - res.refunded_amount));
      out.refunded = round2(r.paid_amount - kept);
      if (res.status === 'refunded') db.exec("UPDATE reservations SET status = 'refunded', paid_amount = 0, balance_due = 0 WHERE id = ?", r.id);
      else db.exec('UPDATE reservations SET paid_amount = ?, balance_due = 0 WHERE id = ?', kept, r.id);
    } catch (e) {
      console.warn('reservation ' + r.id + ' not refunded: ' + e);
      out.refundFailed = true;
    }
  }
  if (r.deposit_status === 'authorized') out[releaseDeposit(r) ? 'released' : 'releaseFailed'] = true;
  return out;
}
// Cancels the deposit hold of a reservation; nothing is charged. Returns true when it is released.
function releaseDeposit(r) {
  try {
    payments.release({reference: depositRef(r)});
  } catch (e) {
    console.warn('deposit hold of reservation ' + r.id + ' not released: ' + e);
    return false;
  }
  db.exec("UPDATE reservations SET deposit_status = 'released' WHERE id = ?", r.id);
  return true;
}
// Tells the owner what a cancellation did with the money, and what is left for them to do.
function moneyNote(r, m) {
  const lines = [];
  if (m.refunded > 0) lines.push('Refunded AED ' + money(m.refunded) + ' to the card.');
  if (m.refundFailed) lines.push('The refund of AED ' + money(r.paid_amount) + ' could not be made: refund it on the Payments page of the admin panel or in Stripe.');
  if (!(r.paid_amount > 0)) lines.push('Nothing was paid online.');
  if (m.released) lines.push('The deposit hold of AED ' + money(r.security_deposit) + ' is released.');
  if (m.releaseFailed) lines.push('The deposit hold could not be released: release it on the Payments page.');
  return lines.join('\n');
}
